/**
 * AuditChart
 * Renders audit statistics as a chart using Chart.js (via react-chartjs-2)
 */
import React, { useEffect, useState } from 'react';
import { Bar, Line, Pie } from 'react-chartjs-2';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  PointElement,
  LineElement,
  ArcElement,
  Tooltip,
  Legend,
} from 'chart.js';
import { auditAPI } from '../services/api';
import './AuditChart.css';

ChartJS.register(
  CategoryScale,
  LinearScale,
  BarElement,
  PointElement,
  LineElement,
  ArcElement,
  Tooltip,
  Legend
);

function AuditChart({ days = 30, action = '', chartType = 'bar' }) {
  const [loading, setLoading] = useState(false);
  const [labels, setLabels] = useState([]);
  const [values, setValues] = useState([]);
  const [error, setError] = useState(null);

  useEffect(() => {
    fetchStats();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [days, action]);

  const fetchStats = async () => {
    setLoading(true);
    setError(null);
    try {
      const params = { days };
      if (action) params.action = action;
      const res = await auditAPI.getAuditStatistics(params);
      const actionStats = res.data.data.actionStats || [];
      const l = actionStats.map((s) => s._id || 'UNKNOWN');
      const v = actionStats.map((s) => s.count || 0);
      setLabels(l);
      setValues(v);
    } catch (err) {
      setError('Failed to load statistics');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const data = {
    labels,
    datasets: [
      {
        label: `Actions (${days} days)`,
        data: values,
        backgroundColor: [
          '#3498db',
          '#27ae60',
          '#f39c12',
          '#e74c3c',
          '#9b59b6',
          '#95a5a6',
          '#16a085',
          '#34495e',
        ],
        borderColor: '#ffffff00',
      },
    ],
  };

  if (loading) return <div className="chart-loading">Loading chart...</div>;
  if (error) return <div className="chart-error">{error}</div>;
  if (!labels.length) return <div className="chart-empty">No data to display.</div>;

  return (
    <div className="audit-chart">
      {chartType === 'bar' && <Bar data={data} />}
      {chartType === 'line' && <Line data={data} />}
      {chartType === 'pie' && <Pie data={data} />}
    </div>
  );
}

export default AuditChart;
